	var kq=1;
	var a=Answer(S4);
	if(LoopIndex()==a){
		kq=0;
		for(var i=1;i<=a;i=i+1){
		if(Contains("S5_"+i,[2,3,4,5,6,7])){kq=kq+1;};
		};
